/* Metre-based lane placement. Coordinates are [latitude, longitude]. */
import {ROAD_LAYOUTS} from './road-layouts.js';
export const LAYOUT_REVISION=3;
export const UPSTREAM_OFFSETS=Object.freeze([5,30,60]);
export const DEFAULT_DOWNSTREAM_OFFSET=10;
const R=6371008.8,rad=Math.PI/180;
export function distanceM(a,b){const lat1=a[0]*rad,lat2=b[0]*rad,dl=(b[0]-a[0])*rad,dn=(b[1]-a[1])*rad;const h=Math.sin(dl/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dn/2)**2;return 2*R*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)));}
export function pathLength(path){return path.slice(1).reduce((n,p,i)=>n+distanceM(path[i],p),0);}
const xy=(p,o)=>[(p[1]-o[1])*rad*R*Math.cos(o[0]*rad),(p[0]-o[0])*rad*R];
const ll=(p,o)=>[o[0]+p[1]/R/rad,o[1]+p[0]/(R*Math.cos(o[0]*rad))/rad];
export function pointAlong(path,metres){if(!Array.isArray(path)||path.length<2||metres<0)throw Error('A lane path and nonnegative distance are required.');let left=metres;for(let i=1;i<path.length;i++){const len=distanceM(path[i-1],path[i]);if(left<=len+1e-6){const t=len?Math.min(left/len,1):0;return [path[i-1][0]+(path[i][0]-path[i-1][0])*t,path[i-1][1]+(path[i][1]-path[i-1][1])*t];}left-=len;}if(left<.01)return [...path.at(-1)];throw Error(`Lane path is too short for ${metres} m.`);}
export function slicePath(path,start,end=pathLength(path)){if(end<start)throw Error('Invalid path interval.');const result=[pointAlong(path,start)];let travelled=0;for(let i=1;i<path.length;i++){travelled+=distanceM(path[i-1],path[i]);if(travelled>start&&travelled<end)result.push([...path[i]]);}const last=pointAlong(path,end);if(distanceM(result.at(-1),last)>.001)result.push(last);return result;}
// Positive offset is to the right looking outward from the intersection.
export function offsetPath(path,offset){const origin=path[0],ps=path.map(p=>xy(p,origin));return ps.map((p,i)=>{const a=ps[Math.max(0,i-1)],b=ps[Math.min(ps.length-1,i+1)],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy)||1;return ll([p[0]+dy/len*offset,p[1]-dx/len*offset],origin);});}
export function bearingDeg(path){const [a,b]=path,delta=xy(b,a);return (Math.atan2(delta[0],delta[1])/rad+360)%360;}
// A detector cross-section uses a perpendicular to the path at its own station.
// Borders are half a lane width from the centre; the centre is not a border.
export function laneCrossSection(lane,station){const total=pathLength(lane.path),center=pointAlong(lane.path,station),before=pointAlong(lane.path,Math.max(0,station-.05)),after=pointAlong(lane.path,Math.min(total,station+.05)),v=xy(after,before),len=Math.hypot(...v);if(len<1e-8)throw Error('Lane tangent is undefined.');const half=(lane.lane_width_m||3)/2,n=[v[1]/len,-v[0]/len];return {center,left:ll([-n[0]*half,-n[1]*half],center),right:ll([n[0]*half,n[1]*half],center),station};}
export function laneEnvelope(lane,length){const end=Math.min(length,pathLength(lane.path)),stations=new Set([0,end]);for(let m=2;m<end;m+=2)stations.add(m);let m=0;for(let i=1;i<lane.path.length;i++){m+=distanceM(lane.path[i-1],lane.path[i]);if(m<end)stations.add(m);}const sections=[...stations].sort((a,b)=>a-b).map(m=>laneCrossSection(lane,m));return {center:sections.map(s=>s.center),left:sections.map(s=>s.left),right:sections.map(s=>s.right)};}
export function moveLaneReference(lane,latitude,longitude,bearing){const old=lane.path[0],o=[latitude,longitude],rotation=(bearing-bearingDeg(lane.path))*rad;const out=structuredClone(lane);out.path=lane.path.map(p=>{const [x,y]=xy(p,old);return ll([x*Math.cos(rotation)+y*Math.sin(rotation),y*Math.cos(rotation)-x*Math.sin(rotation)],o);});out.reference=out.path[0];out.reference_status='Operator-adjusted signal / exit reference; verify on site.';return out;}
export function lanesForLayout(layout){const lanes=[];for(const arm of layout.arms){const bi=arm.inbound_lanes>0&&arm.outbound_lanes>0;for(const flow of ['inbound','outbound']){const count=flow==='inbound'?arm.inbound_lanes:arm.outbound_lanes;for(let i=1;i<=count;i++){const lateral=bi?((flow==='inbound'?-1:1)*(i-.5)+(arm.inbound_lanes-arm.outbound_lanes)/2)*arm.lane_width_m:(i-(count+1)/2)*arm.lane_width_m;const shifted=offsetPath(arm.centerline,lateral),path=slicePath(shifted,arm.reference_m);lanes.push({id:`${layout.id.slice(2)}-${arm.id}-${flow==='inbound'?'IN':'OUT'}-L${i}`,arm_id:arm.id,road_name:arm.road_name,approach:arm.approach,lane_number:i,flow,path,reference:path[0],reference_status:arm.reference_status,lane_width_m:arm.lane_width_m,lateral_offset_m:lateral,geometry_source:arm.geometry_source});}}}return lanes;}
export function roadLayoutFor(id){const data=ROAD_LAYOUTS.find(x=>x.id===id);return data?structuredClone(data):null;}
export function makeLanePucks(j,existing=[]){const old=new Map(existing.map(d=>[d.id,d])),result=[];for(const lane of j.lanes){const upstream=lane.flow==='inbound',offsets=upstream?UPSTREAM_OFFSETS:[j.downstream_offset_m??DEFAULT_DOWNSTREAM_OFFSET];for(const offset of offsets){const pos=pointAlong(lane.path,offset),id=`PUCK-${lane.id}-${upstream?'U':'D'}${String(offset).padStart(2,'0')}`,previous=old.get(id);const unchanged=previous&&distanceM([previous.latitude,previous.longitude],pos)<.02;result.push({...(previous||{}),id,role:'sensor',intersection_id:j.id,lane_id:lane.id,approach:lane.approach,placement:upstream?'upstream':'downstream',offset_m:offset,latitude:pos[0],longitude:pos[1],reference_latitude:lane.path[0][0],reference_longitude:lane.path[0][1],alignment:'lane-path',location_status:'provisional',firmware:previous?.firmware||'pasada-sensor-draft-0.1',commissioning:unchanged?previous.commissioning:{state:'planned',transport:'simulated'}});}}return result;}
export function coverageIssues(project){const issues=[];for(const j of project.intersections){if(!j.layout_revision)continue;for(const lane of j.lanes){const ds=project.devices.filter(d=>d.role==='sensor'&&d.intersection_id===j.id&&d.lane_id===lane.id);const required=lane.flow==='inbound'?UPSTREAM_OFFSETS:[j.downstream_offset_m??DEFAULT_DOWNSTREAM_OFFSET];const placement=lane.flow==='inbound'?'upstream':'downstream';if(ds.length!==required.length||required.some(offset=>ds.filter(d=>d.placement===placement&&d.offset_m===offset).length!==1))issues.push(`${lane.id}: requires ${lane.flow==='inbound'?'exactly 5 / 30 / 60 m upstream':'one downstream counter'}.`);for(const d of ds){try{if(!Number.isFinite(d.reference_latitude)||!Number.isFinite(d.reference_longitude)||distanceM(lane.path[0],[d.reference_latitude,d.reference_longitude])>.05)issues.push(`${d.id}: signal reference metadata is stale.`);const p=pointAlong(lane.path,d.offset_m);if(distanceM([d.latitude,d.longitude],p)>.05)issues.push(`${d.id}: coordinate is not aligned with its lane path.`);}catch(e){issues.push(`${d.id}: ${e.message}`);}}}}return issues;}
export function radioCapacityIssues(project){const budget=project.communications?.encrypted_peer_budget||17;return project.intersections.flatMap(j=>{const count=project.devices.filter(d=>d.intersection_id===j.id&&['sensor','beacon'].includes(d.role)).length;return count>budget?[{intersection_id:j.id,required_peers:count,peer_budget:budget,minimum_receiver_groups:Math.ceil(count/budget),message:`${j.id}: ${count} planned peers exceed a single ${budget}-peer radio group; receiver topology needs review.`}]:[];});}
